/** Funded empty bow is an essential errand; controlled class/level/wallet, actual NPC supplies and resumed combat. */
public class EmptyArrowRestockVerify extends QuestHomeGatekeeperVerify {
 static void empty(Player p)throws Exception{setup(p);p.getStat().setLevel((byte)20);p.getStat().setExp(Experience.LEVEL[20]+1000);erase(p,17);money(p,10000);quietField(p);p.setTarget(null);}
 @SuppressWarnings("unchecked") public static void main(String[] args){try{
  if(!"yes".equals(System.getenv("L2_MOVEMENT_ISOLATED")))throw new IllegalStateException();GameServer.main(new String[0]);Object manager=singleton("AutobotsManager"),m=singleton("offlinelife.OfflineFarmManager"),errands=singleton("population.economy.Errands");invoke(member(m,"travelTask").get(m),"cancel");invoke(member(AutofarmManager.INSTANCE,"onUpdateTask").get(AutofarmManager.INSTANCE),"cancel");gear=singleton("population.economy.Gear");gk=singleton("population.economy.GatekeeperTravel");
  Autobot b=new Autobot(IdFactory.getInstance().getNextId(),PlayerData.getInstance().getTemplate(ClassId.ROGUE),new Appearance((byte)0,(byte)0,(byte)0,Sex.MALE));b.setName("EmptyArrowPolicy");b.setAccessLevel(0);b.setXYZ(npcId(30084).getX()+40,npcId(30084).getY()+40,npcId(30084).getZ());b.getStat().setLevel((byte)20);b.getStat().setExp(Experience.LEVEL[20]+1000);suspendValue(manager,"spawnAutobot",b);((Map<?,?>)invoke(manager,"getActiveBots")).remove(b.getName());invoke(b,"cancelSequence");Thread.sleep(300);Object life=Class.forName("dev.l2j.autobots.population.LifeBehavior").getConstructor(Autobot.class).newInstance(b);invoke(b,"setLife",life);empty(b);
  check("arrows_empty".equals(invoke(errands,"leaveReason",b,System.currentTimeMillis())),"funded empty bow bypasses optional city and productive-hunt timers");
  if(Arrays.asList(args).contains("--plan-only")){System.out.println("EMPTY ARROW RESTOCK PLAN ALL PASSED");System.exit(0);}
  money(b,0);check(invoke(errands,"leaveReason",b,System.currentTimeMillis())==null,"zero wallet cannot promise an unfunded arrow errand");money(b,10000);b.getInventory().addItem("Usable stock fixture",17,1,b,null);check(invoke(errands,"leaveReason",b,System.currentTimeMillis())==null,"one usable arrow does not become an empty-stock emergency");erase(b,17);
  b.getInventory().addItem("Stocked alternate fixture",279,1,b,null);b.getInventory().addItem("Stocked alternate fixture",1341,1,b,null);check(invoke(errands,"leaveReason",b,System.currentTimeMillis())==null,"owned ready alternate bow avoids an unnecessary emergency trip");erase(b,1341);erase(b,279);
  invoke(gear,"noteArrowTrip",b);check(invoke(errands,"leaveReason",b,System.currentTimeMillis())==null,"a failed empty-stock visit cannot immediately repeat");((Map<Integer,Long>)member(gear,"arrowTripRetry").get(gear)).put(b.getObjectId(),System.currentTimeMillis()-1);check("arrows_empty".equals(invoke(errands,"leaveReason",b,System.currentTimeMillis())),"retry interval permits a new funded attempt without a real-time wait");
  net.sf.l2j.gameserver.model.actor.instance.Monster stale=b.getKnownTypeInRadius(net.sf.l2j.gameserver.model.actor.instance.Monster.class,1000).stream().filter(n->!n.isDead()&&n.getTarget()!=b).findFirst().orElseThrow();b.setTarget(stale);CompletableFuture<Object> departure=async(life,"hunt");long casting=System.currentTimeMillis()+8000;while(!b.isCastingNow()&&System.currentTimeMillis()<casting)Thread.sleep(100);check(b.isCastingNow(),"population can leave a stale selected prey when its bow has no arrows");invoke(b,"cancelSequence");b.abortCast();b.stopMove(null);b.setTarget(null);casting=System.currentTimeMillis()+5000;while(!departure.isDone()&&System.currentTimeMillis()<casting)Thread.sleep(100);check(departure.isDone(),"controlled departure cancellation finishes before shop setup");
  Object trip=Class.forName("dev.l2j.autobots.population.economy.TownTrip").getConstructor(Autobot.class,boolean.class).newInstance(b,true);beside(b,npcId(30084));int before=b.getAdena();await(trip,"definition");check(b.getInventory().getInventoryItemCount(17,-1)>=50&&b.getAdena()<before,"population actually pays an ordinary NPC for usable arrow stock");
  Player p=Player.restore(268486152);check(p!=null,"offline owner restores for empty-arrow errand");p.setClient((net.sf.l2j.gameserver.network.GameClient)Class.forName("dev.l2j.autobots.offlinelife.DetachedClient").getConstructor(Player.class).newInstance(p));invoke(AutofarmManager.INSTANCE,"onEnterWorld",p);World.getInstance().addPlayer(p);p.setOnlineStatus(true,true);p.spawnMe(p.getX(),p.getY(),p.getZ());p.onPlayerEnter();((Map<Integer,Player>)member(m,"farming").get(m)).put(p.getObjectId(),p);invoke(m,"openJournal",p);invoke(AutofarmManager.INSTANCE,"quiesce",p);empty(p);net.sf.l2j.gameserver.model.item.instance.ItemInstance forest=p.getInventory().addItem("Viable owned weapon fixture",272,1,p,null);invoke(gear,"equip",p,forest);invoke(AutofarmManager.INSTANCE,"prepareOfflineBehavior",p);Location anchor=location(p);long now=System.currentTimeMillis();for(String name:new String[]{"lastTownTripAt","productiveSince"})((Map<Integer,Long>)member(m,name).get(m)).put(p.getObjectId(),now);AutofarmManager.INSTANCE.startFarm(p);invoke(m,"tick");
  long until=System.currentTimeMillis()+8000;while(System.currentTimeMillis()<until&&!p.isCastingNow()){invoke(m,"tick");Thread.sleep(250);}check(p.isCastingNow(),"offline manager starts its own urgent resupply without optional timer ages");long started=System.currentTimeMillis(),deadline=started+360000;boolean bought=false;
  while(System.currentTimeMillis()<deadline&&!p.isDead()){invoke(m,"tick");bought|=p.getInventory().getInventoryItemCount(17,-1)>=50;if(bought&&AutofarmManager.INSTANCE.isAutoFarming(p)&&gap(location(p),anchor)<700&&!((Map<?,?>)member(m,"townJobs").get(m)).containsKey(p.getObjectId())&&!((Map<?,?>)member(m,"traveling").get(m)).containsKey(p.getObjectId()))break;Thread.sleep(500);}
  check(bought&&!p.isDead()&&gap(location(p),anchor)<700&&AutofarmManager.INSTANCE.isAutoFarming(p),"owner physically buys arrows and returns to the original hunting anchor");long xp=p.getExp();Object combat=((Map<?,?>)member(AutofarmManager.INSTANCE,"combatBehaviors").get(AutofarmManager.INSTANCE)).get(p.getObjectId());deadline=System.currentTimeMillis()+120000;while(System.currentTimeMillis()<deadline&&!p.isDead()&&p.getExp()<=xp){await(AutofarmManager.INSTANCE,"onUpdate",p);Thread.sleep(500);}check(p.getExp()>xp,"ordinary hunting gains real experience after empty-arrow resupply");check(!p.isGM()&&!p.isInvul(),"restock and resumed combat use ordinary core physics");System.out.println("EMPTY ARROW INFO xp="+xp+"->"+p.getExp()+" arrows="+p.getInventory().getInventoryItemCount(17,-1)+" seconds="+(System.currentTimeMillis()-started)/1000);System.out.println("EMPTY ARROW RESTOCK ALL PASSED");System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
